    "css": "button {\n  font-size: 18px;\n  color: #e1e1e1;\n  font-family: inherit;\n  font-weight: 800;\n  cursor: pointer;\n  position: relative;\n  border: none;\n  background: none;\n  text-transform: uppercase;\n  transition-timing-function: cubic-bezier(0.25, 0.8, 0.25, 1);\n  transition-duration: 400ms;\n  transition-property: color;\n}\n\nbutton:focus,\nbutton:hover {\n  color: #fff;\n}\n\nbutton:focus:after,\nbutton:hover:after {\n  width: 100%;\n  left: 0%;\n}\n\nbutton:after {\n  content: \"\";\n  pointer-events: none;\n  bottom: -2px;\n  left: 50%;\n  position: absolute;\n  width: 0%;\n  height: 2px;\n  background-color: #fff;\n  transition-timing-function: cubic-bezier(0.25, 0.8, 0.25, 1);\n  transition-duration: 400ms;\n  transition-property: width, left;\n}"
