    "css": "a {\n  position: relative;\n  display: inline-block;\n  padding: 15px 30px;\n  border: 2px solid #fefefe;\n  text-transform: uppercase;\n  color: #fefefe;\n  text-decoration: none;\n  font-weight: 600;\n  font-size: 20px;\n}\n\na::before {\n  content: '';\n  position: absolute;\n  top: 6px;\n  left: -2px;\n  width: calc(100% + 4px);\n  height: calc(100% - 12px);\n  background-color: #212121;\n  transition: 0.3s ease-in-out;\n  transform: scaleY(1);\n}\n\na:hover::before {\n  transform: scaleY(0);\n}\n\na::after {\n  content: '';\n  position: absolute;\n  left: 6px;\n  top: -2px;\n  height: calc(100% + 4px);\n  width: calc(100% - 12px);\n  background-color: #212121;\n  transition: 0.3s ease-in-out;\n  transform: scaleX(1);\n  transition-delay: 0.5s;\n}\n\na:hover::after {\n  transform: scaleX(0);\n}\n\na span {\n  position: relative;\n  z-index: 3;\n}\n\nbutton {\n  background-color: none;\n  text-decoration: none;\n  background-color: #212121;\n  border: none;\n}"
