    "css": ".Btn {\n  width: 45px;\n  height: 45px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  background-color: transparent;\n  position: relative;\n  /* overflow: hidden; */\n  border-radius: 7px;\n  cursor: pointer;\n  transition: all .3s;\n}\n\n.svgContainer {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: transparent;\n  backdrop-filter: blur(0px);\n  letter-spacing: 0.8px;\n  border-radius: 10px;\n  transition: all .3s;\n  border: 1px solid rgba(156, 156, 156, 0.466);\n}\n\n.BG {\n  position: absolute;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  background: #181818;\n  z-index: -1;\n  border-radius: 10px;\n  pointer-events: none;\n  transition: all .3s;\n}\n\n.Btn:hover .BG {\n  transform: rotate(35deg);\n  transform-origin: bottom;\n}\n\n.Btn:hover .svgContainer {\n  background-color: rgba(156, 156, 156, 0.466);\n  backdrop-filter: blur(4px);\n}\n"
