    "css": ".btn {\n  width: 150px;\n  height: 50px;\n  border-radius: 5px;\n  border: none;\n  transition: all 0.5s ease-in-out;\n  font-size: 20px;\n  font-family: Verdana, Geneva, Tahoma, sans-serif;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  background: #040f16;\n  color: #f5f5f5;\n}\n\n.btn:hover {\n  box-shadow: 0 0 20px 0px #2e2e2e3a;\n}\n\n.btn .icon {\n  position: absolute;\n  height: 40px;\n  width: 70px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  transition: all 0.5s;\n}\n\n.btn .text {\n  transform: translateX(55px);\n}\n\n.btn:hover .icon {\n  width: 175px;\n}\n\n.btn:hover .text {\n  transition: all 0.5s;\n  opacity: 0;\n}\n\n.btn:focus {\n  outline: none;\n}\n\n.btn:active .icon {\n  transform: scale(0.85);\n}"
