    "css": ".btn-cssbuttons {\n --btn-color: #275efe;\n position: relative;\n padding: 16px 32px;\n font-family: Roboto, sans-serif;\n font-weight: 500;\n font-size: 16px;\n line-height: 1;\n color: white;\n background: none;\n border: none;\n outline: none;\n overflow: hidden;\n cursor: pointer;\n filter: drop-shadow(0 2px 8px rgba(39, 94, 254, 0.32));\n transition: 0.3s cubic-bezier(0.215, 0.61, 0.355, 1);\n}\n\n.btn-cssbuttons::before {\n position: absolute;\n content: \"\";\n top: 0;\n left: 0;\n z-index: -1;\n width: 100%;\n height: 100%;\n background: var(--btn-color);\n border-radius: 24px;\n transition: 0.3s cubic-bezier(0.215, 0.61, 0.355, 1);\n}\n\n.btn-cssbuttons span,\n.btn-cssbuttons span span {\n display: inline-flex;\n vertical-align: middle;\n transition: 0.3s cubic-bezier(0.215, 0.61, 0.355, 1);\n}\n\n.btn-cssbuttons span {\n transition-delay: 0.05s;\n}\n\n.btn-cssbuttons span:first-child {\n padding-right: 7px;\n}\n\n.btn-cssbuttons span span {\n margin-left: 8px;\n transition-delay: 0.1s;\n}\n\n.btn-cssbuttons ul {\n position: absolute;\n top: 50%;\n left: 0;\n right: 0;\n display: flex;\n margin: 0;\n padding: 0;\n list-style-type: none;\n transform: translateY(-50%);\n}\n\n.btn-cssbuttons ul li {\n flex: 1;\n}\n\n.btn-cssbuttons ul li a {\n display: inline-flex;\n vertical-align: middle;\n transform: translateY(55px);\n transition: 0.3s cubic-bezier(0.215, 0.61, 0.355, 1);\n}\n\n.btn-cssbuttons ul li a:hover {\n opacity: 0.5;\n}\n\n.btn-cssbuttons:hover::before {\n transform: scale(1.2);\n}\n\n.btn-cssbuttons:hover span,\n.btn-cssbuttons:hover span span {\n transform: translateY(-55px);\n}\n\n.btn-cssbuttons:hover ul li a {\n transform: translateY(0);\n}\n\n.btn-cssbuttons:hover ul li:nth-child(1) a {\n transition-delay: 0.15s;\n}\n\n.btn-cssbuttons:hover ul li:nth-child(2) a {\n transition-delay: 0.2s;\n}\n\n.btn-cssbuttons:hover ul li:nth-child(3) a {\n transition-delay: 0.25s;\n}"
