    "css": ".button {\n  width: 50px;\n  height: 50px;\n  border-radius: 50%;\n  background-color: rgb(20, 20, 20);\n  border: none;\n  font-weight: 600;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0px 0px 20px rgba(0, 0, 0, 0.164);\n  cursor: pointer;\n  transition-duration: .3s;\n  overflow: hidden;\n  position: relative;\n}\n\n.svgIcon {\n  width: 12px;\n  transition-duration: .3s;\n}\n\n.svgIcon path {\n  fill: white;\n}\n\n.button:hover {\n  width: 140px;\n  border-radius: 50px;\n  transition-duration: .3s;\n  background-color: rgb(255, 69, 69);\n  align-items: center;\n}\n\n.button:hover .svgIcon {\n  width: 50px;\n  transition-duration: .3s;\n  transform: translateY(60%);\n}\n\n.button::before {\n  position: absolute;\n  top: -20px;\n  content: \"Delete\";\n  color: white;\n  transition-duration: .3s;\n  font-size: 2px;\n}\n\n.button:hover::before {\n  font-size: 13px;\n  opacity: 1;\n  transform: translateY(30px);\n  transition-duration: .3s;\n}"
