    "css": ".flex {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n}\n.outer-cont {\n  padding: 12px 20px;\n  border: none;\n  font-size: 1rem;\n  cursor: pointer;\n  position: relative;\n  background: linear-gradient(90deg, #5bfcc4, #f593e4, #71a4f0);\n  border-radius: 12px;\n  color: #fff;\n  transition: all 0.3s ease;\n  box-shadow:\n    inset 0px 0px 5px #ffffffa9,\n    inset 0px 35px 30px #000,\n    0px 5px 10px #000000cc;\n  text-shadow: 1px 1px 1px #000;\n}\n.outer-cont::before {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  margin: auto;\n  border-radius: 12px;\n  filter: blur(0);\n  z-index: -1;\n  box-shadow: none;\n  background: conic-gradient(\n    #00000000 80deg,\n    #40baf7,\n    #f34ad7,\n    #5bfcc4,\n    #00000000 280deg\n  );\n  transition: all 0.3s ease;\n}\n.outer-cont:hover::before {\n  filter: blur(15px);\n}\n.outer-cont:active::before {\n  filter: blur(5px);\n  transform: translateY(1px);\n}\n.outer-cont:active {\n  box-shadow:\n    inset 0px 0px 5px #ffffffa9,\n    inset 0px 35px 30px #000;\n  margin-top: 3px;\n}\n"
