    "css": ".fancy {\n  background-color: transparent;\n  border: 2px solid #fff;\n  border-radius: 0;\n  box-sizing: border-box;\n  color: #000;\n  cursor: pointer;\n  display: inline-block;\n  float: right;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  margin: 0;\n  outline: none;\n  overflow: visible;\n  padding: 1.25em 2em;\n  position: relative;\n  text-align: center;\n  text-decoration: none;\n  text-transform: none;\n  transition: all 0.3s ease-in-out;\n  user-select: none;\n  font-size: 13px;\n}\n\n.fancy::before {\n  content: \" \";\n  width: 1.5625rem;\n  height: 2px;\n  background: white;\n  top: 50%;\n  left: 1.5em;\n  position: absolute;\n  transform: translateY(-50%);\n  transform-origin: center;\n  transition: background 0.3s linear, width 0.3s linear;\n}\n\n.fancy .text {\n  font-size: 1.125em;\n  line-height: 1.33333em;\n  padding-left: 2em;\n  display: block;\n  text-align: left;\n  transition: all 0.3s ease-in-out;\n  text-transform: uppercase;\n  text-decoration: none;\n  color: white;\n}\n\n.fancy .top-key {\n  height: 2px;\n  width: 1.5625rem;\n  top: -2px;\n  left: 0.625rem;\n  position: absolute;\n  background: #212121;\n  transition: width 0.5s ease-out, left 0.3s ease-out;\n}\n\n.fancy .bottom-key-1 {\n  height: 2px;\n  width: 1.5625rem;\n  right: 1.875rem;\n  bottom: -2px;\n  position: absolute;\n  background: #212121;\n  transition: width 0.5s ease-out, right 0.3s ease-out;\n}\n\n.fancy .bottom-key-2 {\n  height: 2px;\n  width: 0.625rem;\n  right: 0.625rem;\n  bottom: -2px;\n  position: absolute;\n  background: #212121;\n  transition: width 0.5s ease-out, right 0.3s ease-out;\n}\n\n.fancy:hover {\n  color: white;\n  background: white;\n}\n\n.fancy:hover::before {\n  width: 0.9375rem;\n  background: black;\n}\n\n.fancy:hover .text {\n  color: black;\n  padding-left: 1.5em;\n}\n\n.fancy:hover .top-key {\n  left: -2px;\n  width: 0px;\n}\n\n.fancy:hover .bottom-key-1,\n .fancy:hover .bottom-key-2 {\n  right: 0;\n  width: 0;\n}"
