    "css": ".button {\n  --main-focus: #2d8cf0;\n  --font-color: #dedede;\n  --bg-color-sub: #222;\n  --bg-color: #323232;\n  --main-color: #dedede;\n  position: relative;\n  width: 150px;\n  height: 40px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  border: 2px solid var(--main-color);\n  box-shadow: 4px 4px var(--main-color);\n  background-color: var(--bg-color);\n  border-radius: 10px;\n  overflow: hidden;\n}\n\n.button, .button__icon, .button__text {\n  transition: all 0.3s;\n}\n\n.button .button__text {\n  transform: translateX(21px);\n  color: var(--font-color);\n  font-weight: 600;\n}\n\n.button .button__icon {\n  position: absolute;\n  transform: translateX(109px);\n  height: 100%;\n  width: 39px;\n  background-color: var(--bg-color-sub);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.button .svg {\n  width: 20px;\n  fill: var(--main-color);\n}\n\n.button:hover {\n  background: var(--bg-color);\n}\n\n.button:hover .button__text {\n  color: transparent;\n}\n\n.button:hover .button__icon {\n  width: 148px;\n  transform: translateX(0);\n}\n\n.button:active {\n  transform: translate(3px, 3px);\n  box-shadow: 0px 0px var(--main-color);\n}"
