    "css": ".Btn {\n  width: 130px;\n  height: 40px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: rgb(15, 15, 15);\n  border: none;\n  color: white;\n  font-weight: 600;\n  gap: 8px;\n  cursor: pointer;\n  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.103);\n  position: relative;\n  overflow: hidden;\n  transition-duration: .3s;\n}\n\n.svgIcon {\n  width: 16px;\n}\n\n.svgIcon path {\n  fill: white;\n}\n\n.Btn::before {\n  width: calc(100% + 40px);\n  aspect-ratio: 1/1;\n  position: absolute;\n  content: \"\";\n  background-color: white;\n  border-radius: 50%;\n  left: -20px;\n  top: 50%;\n  transform: translate(-150%, -50%);\n  transition-duration: .5s;\n  mix-blend-mode: difference;\n}\n\n.Btn:hover::before {\n  transform: translate(0, -50%);\n}\n\n.Btn:active {\n  transform: translateY(4px);\n  transition-duration: .3s;\n}"
