    "css": "/* <reset-style> ============================ */\nbutton {\n  border: none;\n  background: none;\n  padding: 0;\n  margin: 0;\n  cursor: pointer;\n  font-family: inherit;\n}\n/* <main-style> ============================ */\n.menu__button {\n  min-width: 62px;\n  height: 36px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 8px 16px;\n  border: 1px solid #fff;\n  background-color: transparent;\n  transition: background-color .4s;\n}\n\n.menu__button:hover {\n  background-color: #fff;\n}\n\n.menu__button span {\n  color: #fff;\n  line-height: 1;\n  transition: color .4s;\n}\n\n.menu__button:hover span {\n  color: #000;\n}"
