    "css": ".absolute {\n  position: absolute\n}\n\n.relative {\n  position: relative\n}\n\n.-top-\\[150\\%\\] {\n  top: -150%\n}\n\n.left-0 {\n  left: 0px\n}\n\n.inline-flex {\n  display: inline-flex\n}\n\n.h-\\[5px\\] {\n  height: 5px\n}\n\n.w-80 {\n  width: 20rem\n}\n\n.overflow-hidden {\n  overflow: hidden\n}\n\n.rounded-md {\n  border-radius: 0.375rem\n}\n\n.border {\n  border-width: 1px\n}\n\n.border-b-4 {\n  border-bottom-width: 4px\n}\n\n.border-neutral-400 {\n  --tw-border-opacity: 1;\n  border-color: rgb(163 163 163 / var(--tw-border-opacity))\n}\n\n.bg-neutral-400 {\n  --tw-bg-opacity: 1;\n  background-color: rgb(163 163 163 / var(--tw-bg-opacity))\n}\n\n.bg-neutral-950 {\n  --tw-bg-opacity: 1;\n  background-color: rgb(10 10 10 / var(--tw-bg-opacity))\n}\n\n.px-4 {\n  padding-left: 1rem;\n  padding-right: 1rem\n}\n\n.py-2 {\n  padding-top: 0.5rem;\n  padding-bottom: 0.5rem\n}\n\n.font-medium {\n  font-weight: 500\n}\n\n.text-neutral-400 {\n  --tw-text-opacity: 1;\n  color: rgb(163 163 163 / var(--tw-text-opacity))\n}\n\n.opacity-50 {\n  opacity: 0.5\n}\n\n.shadow-\\[0_0_10px_10px_rgba\\(0\\2c 0\\2c 0\\2c 0\\.3\\)\\] {\n  --tw-shadow: 0 0 10px 10px rgba(0,0,0,0.3);\n  --tw-shadow-colored: 0 0 10px 10px var(--tw-shadow-color);\n  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)\n}\n\n.shadow-neutral-400 {\n  --tw-shadow-color: #a3a3a3;\n  --tw-shadow: var(--tw-shadow-colored)\n}\n\n.outline-none {\n  outline: 2px solid transparent;\n  outline-offset: 2px\n}\n\n.duration-300 {\n  transition-duration: 300ms\n}\n\n.duration-500 {\n  transition-duration: 500ms\n}\n\n.hover\\:border-b:hover {\n  border-bottom-width: 1px\n}\n\n.hover\\:border-t-4:hover {\n  border-top-width: 4px\n}\n\n.hover\\:brightness-150:hover {\n  --tw-brightness: brightness(1.5);\n  filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow)\n}\n\n.active\\:opacity-75:active {\n  opacity: 0.75\n}\n\n.group:hover .group-hover\\:top-\\[150\\%\\] {\n  top: 150%\n}"
