    "css": ".button {\n  cursor: pointer;\n  background: none;\n  border: none;\n  display: flex;\n  flex-direction: column;\n  width: 70px;\n  gap: 4px;\n}\n\n.button:hover {\n  animation: move 2s infinite ease;\n}\n\n@keyframes move {\n  0% {\n    transform: translateX(0);\n  }\n\n  50% {\n    transform: translateX(20px);\n  }\n\n  100% {\n    transform: translateX(0);\n  }\n}\n\n.round {\n  width: 6px;\n  height: 6px;\n  background: #3da9fc;\n  border-radius: 50%;\n}\n\n.line {\n  display: flex;\n  gap: 4px;\n}\n\n.two {\n  transform: translateX(10px);\n}\n\n.three {\n  transform: translateX(20px);\n}\n\n.four {\n  transform: translateX(30px);\n}\n\n.five {\n  transform: translateX(20px);\n}\n\n.six {\n  transform: translateX(10px);\n}"
