    "css": ".container {\n  background: #ff6f6f;\n  border-radius: 15px;\n  padding: 15px;\n  display: flex;\n  gap: 15px;\n  box-shadow: 3px 5px 10px #ff7a7a, inset 3px 0 0 #ff5751d6,\n    inset -3px 0 0 #ff5751d6, inset 0 3px 0 #ffffff23, inset 0 -3px 0 #00000023;\n}\n.btn {\n  text-decoration: none;\n  border: none;\n  outline: none;\n  background: #ff6f6f;\n  padding: 10px;\n  box-shadow: 0 0 5px #0000005a, 2px 2px 3px #00000078,\n    inset 1px 1px 2px #ffffff9d;\n  border-radius: 10px;\n  color: #fff;\n  font-size: 16px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: all 0.2s;\n  font-family: sans-serif;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n.btn:focus {\n  animation: 0.3s clicked linear;\n}\n.cmd {\n  display: flex;\n  gap: 10px;\n  flex-direction: column;\n  justify-content: center;\n  align-items: flex-end;\n}\n.c {\n  width: 75px;\n  font-size: 1.5rem;\n}\n@keyframes clicked {\n  0% {\n    transform: scale(1);\n  }\n  50% {\n    transform: scale(0.95);\n    box-shadow: 0 0 5px #00000067, inset 0 0 3px #ffffff78;\n  }\n  100% {\n    transform: scale(1);\n  }\n}\n"
