    "css": ".Btn {\n  width: 45px;\n  height: 45px;\n  /* border: none; */\n  border-radius: 50%;\n  background-color: #00acee;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  position: relative;\n  transition-duration: .5s;\n  box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.137);\n  border: 2px solid #bbecff;\n}\n\n.logoIcon {\n  fill: white;\n}\n\n.tooltip {\n  position: absolute;\n  top: -20px;\n  opacity: 0;\n  background-color: #00acee;\n  color: white;\n  padding: 5px 10px;\n  border-radius: 5px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition-duration: .2s;\n  pointer-events: none;\n  letter-spacing: 0.5px;\n}\n\n.tooltip::before {\n  position: absolute;\n  content: \"\";\n  width: 10px;\n  height: 10px;\n  background-color: #00acee;\n  background-size: 1000%;\n  background-position: center;\n  transform: rotate(45deg);\n  bottom: -20%;\n  transition-duration: .3s;\n}\n\n.Btn:hover .tooltip {\n  top: -45px;\n  opacity: 1;\n  transition-duration: .3s;\n}\n\n.Btn:hover {\n  background-position: right;\n  transition-duration: .5s;\n}"
