    "css": "button {\n  color: white;\n  background-color: #10B981;\n  --ring-color: #6EE7B7;\n  font-weight: 500;\n  border-radius: 0.5rem;\n  font-size: 1rem;\n  line-height: 2rem;\n  padding-left: 2rem;\n  padding-right: 2rem;\n  padding-top: 0.7rem;\n  padding-bottom: 0.7rem;\n  text-align: center;\n  margin-right: 0.5rem;\n  display: inline-flex;\n  align-items: center;\n  border: none;\n}\n\nbutton:hover {\n  background-color: #059669;\n}\n\nbutton:focus {\n  box-shadow: var(--tw-ring-inset) 0 0 0 calc(4px + var(--tw-ring-offset-width)) var(--tw-ring-color);\n}\n\nbutton svg {\n  display: inline;\n  width: 1.3rem;\n  height: 1.3rem;\n  margin-right: 0.75rem;\n  color: white;\n  animation: bounce 1s infinite;\n}\n\n@keyframes bounce {\n  0%, 100% {\n    transform: translateY(-5px);\n  }\n\n  50% {\n    transform: translateY(5px);\n  }\n}"
