    "css": ".button {\n  height: 4em;\n  width: 12em;\n  border-radius: 18px;\n  border: 4px solid lightskyblue;\n  padding: 0.2em;\n  overflow: hidden;\n}\n\n.text {\n  display: block;\n  font-size: 20px;\n  color: lightskyblue;\n}\n\n.afterText {\n  display: none;\n}\n\n.clouds {\n  display: none;\n  height: 4rem;\n  width: 8rem;\n}\n\n.button:hover {\n  cursor: pointer;\n}\n\n.button:hover .text {\n  text-decoration: underline;\n  font-weight: bold;\n}\n\n.button:focus {\n  transition: ease-in 200ms;\n  background-color: lightskyblue;\n  border: none;\n}\n\n.button:focus .text {\n  display: none;\n}\n\n.button:focus .afterText {\n  animation: hoverMovement 1s ease-in alternate infinite;\n  display: block;\n  font-size: 25px;\n  letter-spacing: 5px;\n  color: rgb(90, 94, 97);\n}\n\n.button:focus .clouds {\n  display: block;\n  animation: cloudMovement ease-in-out 3s infinite;\n  margin-top: -1.5em;\n}\n\n@keyframes hoverMovement {\n  from {\n    transform: translateY(0em);\n  }\n\n  to {\n    transform: translateY(-0.1em);\n  }\n}\n\n@keyframes cloudMovement {\n  from {\n    transform: translateX(-5em);\n  }\n\n  to {\n    transform: translateX(10em);\n  }\n}"
