    "css": ".button {\n  --bg-color: #fff;\n  --main-color: #323232;\n  width: 40px;\n  height: 40px;\n  border-radius: 100%;\n  border: 2px solid var(--main-color);\n  background-color: var(--bg-color);\n  box-shadow: 4px 4px var(--main-color);\n  font-size: 25px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  transition: all 0.2s;\n  cursor: pointer;\n}\n\n.button:active {\n  box-shadow: 0px 0px var(--main-color);\n  transform: translate(3px, 3px);\n}\n\n.icon {\n  width: 24px;\n  height: 24px;\n  fill: var(--main-color);\n}"
