    "css": "button {\n  background: linear-gradient(30deg, #000 35%, #ea8b19 73%);\n  position: relative;\n  padding: 17px 45px;\n  font-size: 20px;\n  font-weight: 500;\n  color: white;\n  border: 3px solid #ea8b19;\n  border-radius: 8px;\n  transition: all .3s ease-in-out;\n}\n\n.star-1 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 20%;\n  left: 20%;\n  width: 25px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all 1s cubic-bezier(0.05, 0.83, 0.43, 0.96);\n}\n\n.star-2 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 45%;\n  left: 45%;\n  width: 15px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all 1s cubic-bezier(0, 0.4, 0, 1.01);\n}\n\n.star-3 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 40%;\n  left: 40%;\n  width: 5px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all 1s cubic-bezier(0, 0.4, 0, 1.01);\n}\n\n.star-4 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 20%;\n  left: 40%;\n  width: 8px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all .8s cubic-bezier(0, 0.4, 0, 1.01);\n}\n\n.star-5 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 25%;\n  left: 45%;\n  width: 15px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all .6s cubic-bezier(0, 0.4, 0, 1.01);\n}\n\n.star-6 {\n  position: absolute;\n  fill: #ea8b19;\n  top: 5%;\n  left: 50%;\n  width: 5px;\n  height: auto;\n  filter: drop-shadow(0 0 0 #ea8b19);\n  z-index: -5;\n  transition: all .8s ease;\n}\n\nbutton:hover {\n  background: #000;\n  color: #ea8b19;\n  box-shadow: 0 0 50px #ea8b19;\n}\n\nbutton:hover .star-1 {\n  position: absolute;\n  top: -110%;\n  left: -60%;\n  width: 30px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\nbutton:hover .star-2 {\n  position: absolute;\n  top: -45%;\n  left: 0%;\n  width: 20px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\nbutton:hover .star-3 {\n  position: absolute;\n  top: 55%;\n  left: 15%;\n  width: 11px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\nbutton:hover .star-4 {\n  position: absolute;\n  top: 45%;\n  left: 85%;\n  width: 15px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\nbutton:hover .star-5 {\n  position: absolute;\n  top: 25%;\n  left: 140%;\n  width: 25px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\nbutton:hover .star-6 {\n  position: absolute;\n  top: -5%;\n  left: 60%;\n  width: 15px;\n  height: auto;\n  filter: drop-shadow(0 0 10px #ea8b19);\n  z-index: 2;\n}\n\n.fil0 {\n  fill: #ea8b19;\n}\n\n.box {\n  width: 120px;\n  height: 45px;\n  float: left;\n  transition: .5s linear;\n  position: relative;\n  display: block;\n  padding: 8px;\n  margin: -10px -15.5px;\n  background: transparent;\n  text-transform: uppercase;\n  font-weight: 900;\n}\n\n.box:hover {\n  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.5);\n  cursor: pointer;\n  color: white;\n  background: black;\n}\n\n.box:hover:before {\n  border-color: #fff;\n  height: 100%;\n  transform: translateX(0);\n  transition: .3s transform linear, .3s height linear .3s;\n}\n\n.box:hover:after {\n  border-color: #ea8b19;\n  height: 100%;\n  transform: translateX(0);\n  transition: .3s transform linear, .3s height linear .5s;\n}\n\n.box:before {\n  position: absolute;\n  content: '';\n  left: 0;\n  bottom: 0;\n  height: 4px;\n  width: 100%;\n  border-bottom: 4px solid transparent;\n  border-left: 4px solid transparent;\n  box-sizing: border-box;\n  transform: translateX(100%);\n}\n\n.box:after {\n  position: absolute;\n  content: '';\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 4px;\n  border-top: 4px solid transparent;\n  border-right: 4px solid transparent;\n  box-sizing: border-box;\n  transform: translateX(-100%);\n}\n"
