    "css": "button {\n  margin: 0.5cm;\n}\n.Btn {\n  width: 45px;\n  height: 45px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  background-color: transparent;\n  position: relative;\n  /* overflow: hidden; */\n  border-radius: 7px;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.svgContainer {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: transparent;\n  backdrop-filter: blur(0px);\n  letter-spacing: 0.8px;\n  border-radius: 10px;\n  transition: all 0.3s;\n  border: 1px solid rgba(156, 156, 156, 0.466);\n}\n\n.BG {\n  position: absolute;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  background: #24a1de;\n  z-index: -1;\n  border-radius: 10px;\n  pointer-events: none;\n  transition: all 0.3s;\n}\n\n.Btn:hover .BG {\n  transform: rotate(35deg);\n  transform-origin: bottom;\n}\n\n.Btn:hover .svgContainer {\n  border: 1px solid rgba(226, 226, 226, 0.466);\n  background-color: rgba(204, 204, 204, 0.466);\n  backdrop-filter: blur(4px);\n}\n\n.Btntwit {\n  width: 45px;\n  height: 45px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  background-color: transparent;\n  position: relative;\n  /* overflow: hidden; */\n  border-radius: 7px;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.svgContainertwit {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: transparent;\n  backdrop-filter: blur(0px);\n  letter-spacing: 0.8px;\n  border-radius: 10px;\n  transition: all 0.3s;\n  border: 1px solid rgba(156, 156, 156, 0.466);\n}\n\n.BGtwit {\n  position: absolute;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  background: #181818;\n  z-index: -1;\n  border-radius: 10px;\n  pointer-events: none;\n  transition: all 0.3s;\n}\n\n.Btntwit:hover .BGtwit {\n  transform: rotate(35deg);\n  transform-origin: bottom;\n}\n\n.Btntwit:hover .svgContainertwit {\n  background-color: rgba(156, 156, 156, 0.466);\n  backdrop-filter: blur(4px);\n}\n\n.Btninsta {\n  width: 45px;\n  height: 45px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  background-color: transparent;\n  position: relative;\n  /* overflow: hidden; */\n  border-radius: 3px;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.svgContainerinsta {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: transparent;\n  backdrop-filter: blur(4px);\n  letter-spacing: 0.8px;\n  border-radius: 10px;\n  transition: all 0.3s;\n  border: 1px solid rgba(156, 156, 156, 0.466);\n}\n\n.BGinsta {\n  position: absolute;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  background: #f09433;\n  background: -moz-linear-gradient(\n    45deg,\n    #f09433 0%,\n    #e6683c 25%,\n    #dc2743 50%,\n    #cc2366 75%,\n    #bc1888 100%\n  );\n  background: -webkit-linear-gradient(\n    45deg,\n    #f09433 0%,\n    #e6683c 25%,\n    #dc2743 50%,\n    #cc2366 75%,\n    #bc1888 100%\n  );\n  background: linear-gradient(\n    45deg,\n    #f09433 0%,\n    #e6683c 25%,\n    #dc2743 50%,\n    #cc2366 75%,\n    #bc1888 100%\n  );\n  filter: progid:DXImageTransform.Microsoft.gradient( startColorstr='#f09433', endColorstr='#bc1888',GradientType=1 );\n  z-index: -1;\n  border-radius: 9px;\n  pointer-events: none;\n  transition: all 0.3s;\n}\n\n.Btninsta:hover .BGinsta {\n  transform: rotate(35deg);\n  transform-origin: bottom;\n}\n\n.Btninsta:hover .svgContainerinsta {\n  background-color: rgba(156, 156, 156, 0.466);\n}\n\n.Btnstock {\n  width: 45px;\n  height: 45px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: none;\n  background-color: transparent;\n  position: relative;\n  /* overflow: hidden; */\n  border-radius: 7px;\n  cursor: pointer;\n  transition: all 0.3s;\n}\n\n.svgContainerstock {\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: transparent;\n  backdrop-filter: blur(0px);\n  letter-spacing: 0.8px;\n  border-radius: 10px;\n  transition: all 0.3s;\n  border: 1px solid rgba(156, 156, 156, 0.466);\n}\n\n.BGstock {\n  position: absolute;\n  content: \"\";\n  width: 100%;\n  height: 100%;\n  background: #f48024;\n  z-index: -1;\n  border-radius: 10px;\n  pointer-events: none;\n  transition: all 0.3s;\n}\n\n.Btnstock:hover .BGstock {\n  transform: rotate(35deg);\n  transform-origin: bottom;\n}\n\n.Btnstock:hover .svgContainerstock {\n  background-color: rgba(202, 202, 202, 0.466);\n  backdrop-filter: blur(4px);\n}\n"
