    "css": ".button {\n  font-family: Verdana, Geneva, Tahoma, sans-serif;\n  font-weight: 400;\n  background: #f2295b;\n  color: white;\n  padding: 0.35em 0;\n  font-size: 17px;\n  border: none;\n  border-radius: 0.7em;\n  letter-spacing: 0.08em;\n  position: relative;\n  display: flex;\n  align-content: center;\n  align-items: center;\n  overflow: hidden;\n  height: 2.7em;\n  padding-left: 3em;\n  padding-right: 0.5em;\n}\n\n.button .icon {\n  background: #fff;\n  margin-right: 1em;\n  height: 2.2em;\n  width: 2.2em;\n  border-radius: 0.5em;\n  position: absolute;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  left: 0.2em;\n  transition: all .7s;\n  gap: 10px;\n}\n\n.shere {\n  width: 1.3rem;\n  height: 1.3rem;\n}\n\n.button:hover .icon {\n  width: calc(100% - 0.6rem);\n}\n\n.button:hover .shere {\n  width: calc(100% - 0.6rem);\n  display: none;\n}\n\n.button .icon-shere {\n  color: #f2295b;\n  width: 1.5rem;\n  height: 1.5rem;\n  display: none;\n}\n\n.button:hover .icon .icon-shere {\n  display: flex;\n}"
