    "css": ".btn {\n  width: 130px;\n  height: 40px;\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 10px;\n  letter-spacing: 2.5px;\n  text-transform: uppercase;\n  border: 1px solid black;\n}\n\n.btn,\n.socials {\n  border-radius: 20px;\n  background-color: transparent;\n  filter: drop-shadow(1px 1px 3px rgba(122, 122, 122, 0.808));\n}\n\n.socials {\n  position: absolute;\n  /* border-bottom: 0.2px solid black; */\n  width: 100%;\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: space-around;\n  list-style: none;\n  top: 0;\n  left: 0;\n  transition: .2s linear;\n  opacity: 0;\n  visibility: hidden;\n}\n\n.btn:hover > .socials {\n  opacity: 1;\n  visibility: visible;\n  top: -120%;\n}"
