    "css": ".btn-9,\n.btn-9 *,\n.btn-9 :after,\n.btn-9 :before,\n.btn-9:after,\n.btn-9:before {\n  border: 0 solid;\n  box-sizing: border-box;\n}\n\n.btn-9 {\n  -webkit-tap-highlight-color: transparent;\n  -webkit-appearance: button;\n  background-color: #000;\n  background-image: none;\n  color: #fff;\n  cursor: pointer;\n  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,\n    Segoe UI, Roboto, Helvetica Neue, Arial, Noto Sans, sans-serif,\n    Apple Color Emoji, Segoe UI Emoji, Segoe UI Symbol, Noto Color Emoji;\n  font-size: 100%;\n  font-weight: 900;\n  line-height: 1.5;\n  margin: 0;\n  -webkit-mask-image: -webkit-radial-gradient(#000, #fff);\n  padding: 0;\n  text-transform: uppercase;\n}\n\n.btn-9:disabled {\n  cursor: default;\n}\n\n.btn-9:-moz-focusring {\n  outline: auto;\n}\n\n.btn-9 svg {\n  display: block;\n  vertical-align: middle;\n}\n\n.btn-9 [hidden] {\n  display: none;\n}\n\n.btn-9 {\n  border-radius: 99rem;\n  border-width: 2px;\n  overflow: hidden;\n  padding: 0.8rem 3rem;\n  position: relative;\n}\n\n.btn-9 span {\n  mix-blend-mode: difference;\n}\n\n.btn-9:after,\n.btn-9:before {\n  --tilt: 1.2rem;\n  background: #fff;\n  -webkit-clip-path: polygon(\n    0 0,\n    calc(100% - var(--tilt)) 0,\n    100% 50%,\n    calc(100% - var(--tilt)) 100%,\n    0 100%\n  );\n  clip-path: polygon(\n    0 0,\n    calc(100% - var(--tilt)) 0,\n    100% 50%,\n    calc(100% - var(--tilt)) 100%,\n    0 100%\n  );\n  content: \"\";\n  display: block;\n  height: 100%;\n  left: calc(-100% - var(--tilt));\n  position: absolute;\n  top: 0;\n  transform: translateX(var(--progress, 0));\n  transition: transform 0.2s ease;\n  width: calc(100% + var(--tilt));\n}\n\n.btn-9:after {\n  left: 100%;\n  transform: translateX(var(--progress, 0)) rotate(180deg);\n  z-index: -1;\n}\n\n.btn-9:hover:before {\n  --progress: 100%;\n}\n\n.btn-9:hover:after {\n  --progress: -100%;\n}\n"
