    "css": ".CartBtn {\n  width: 140px;\n  height: 40px;\n  border-radius: 12px;\n  border: none;\n  background-color: rgb(255, 208, 0);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  transition-duration: .5s;\n  overflow: hidden;\n  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.103);\n  position: relative;\n}\n\n.IconContainer {\n  position: absolute;\n  left: -50px;\n  width: 30px;\n  height: 30px;\n  background-color: transparent;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  overflow: hidden;\n  z-index: 2;\n  transition-duration: .5s;\n}\n\n.icon {\n  border-radius: 1px;\n}\n\n.text {\n  height: 100%;\n  width: fit-content;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: rgb(17, 17, 17);\n  z-index: 1;\n  transition-duration: .5s;\n  font-size: 1.04em;\n  font-weight: 600;\n}\n\n.CartBtn:hover .IconContainer {\n  transform: translateX(58px);\n  border-radius: 40px;\n  transition-duration: .5s;\n}\n\n.CartBtn:hover .text {\n  transform: translate(10px,0px);\n  transition-duration: .5s;\n}\n\n.CartBtn:active {\n  transform: scale(0.95);\n  transition-duration: .5s;\n}"
