    "css": "button {\n  background-color: transparent;\n  width: 13em;\n  height: 3.3em;\n  border: 2px solid #1abc9c;\n  border-radius: 25px;\n  font-weight: bold;\n  text-transform: uppercase;\n  color: #1abc9c;\n  padding: 2px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  position: relative;\n  overflow: hidden;\n  cursor: pointer;\n}\n\nbutton .txt {\n  transition: .4s ease-in-out;\n  position: absolute;\n}\n\nbutton .txt2 {\n  transform: translateY(1em) scale(0);\n  color: #212121;\n  position: absolute;\n}\n\nbutton .loader-container {\n  height: 100%;\n  width: 100%;\n  background-color: transparent;\n  border-radius: inherit;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  z-index: -1;\n  overflow: hidden;\n}\n\nbutton .loader-container .loader {\n  height: 100%;\n  width: 100%;\n  background-color: #1abc9c;\n  border-radius: inherit;\n  transform: translateX(-13em);\n}\n\nbutton:focus {\n  transition: .4s ease-in-out .4s;\n  animation: scaling 1.5s ease-in-out 0s 1 both;\n}\n\nbutton:focus .txt {\n  position: absolute;\n  transform: translateY(-5em);\n  transition: .4s ease-in-out;\n}\n\nbutton:focus .txt2 {\n  transform: translateY(0) scale(1);\n  transition: .3s ease-in-out 1.7s;\n}\n\nbutton:focus .loader {\n  display: block;\n  transform: translate(0);\n  transition: .8s cubic-bezier(0,.4,1,.28) .4s;\n  animation: loading;\n}\n\n@keyframes scaling {\n  20% {\n    height: 1.5em;\n  }\n\n  80% {\n    height: 1.5em;\n  }\n\n  100% {\n    height: 3.3em;\n  }\n}"
