    "css": "button {\n  background: #282936;\n  padding: 10px 2rem;\n  outline: 2.5px solid #FEBF00;\n  outline-offset: 3px;\n  border: 0;\n  color: white;\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  font-size: 1rem;\n  border-radius: 100rem;\n  transition: 0.4s;\n  font-weight: 600;\n}\n\nbutton:hover {\n  outline-offset: 4.5px;\n  background: #FEBF00;\n  font-size: 1.1rem;\n}"
