    "css": ".button {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  border-radius: 7px;\n  border: none;\n  background: #0ba360;\n  background: linear-gradient(\n    to right,\n    #0ba360,#3cba92\n  );\n  color: white;\n  font-family: inherit;\n  text-align: center;\n  font-size: 13px;\n  box-shadow: 0px 14px 56px -11px #0ba360;\n  width: 11em;\n  padding: 0.7em;\n  transition: all 0.4s;\n  cursor: pointer;\n}\n\n.button svg {\n  width: 25px;\n  height: 25px;\n}\n\n.button svg path {\n  fill: white\n}\n\n.button span {\n  cursor: pointer;\n  display: inline-block;\n  position: relative;\n  transition: 0.4s;\n}\n\n.button span:after {\n  content: 'for free';\n  position: absolute;\n  opacity: 0;\n  top: 0;\n  right: -20px;\n  transition: 0.7s;\n}\n\n.button:hover span {\n  padding-right: 3.80em;\n}\n\n.button:hover span:after {\n  opacity: 4;\n  right: 0;\n}"
