    "css": ".not_found_body {\n  min-height: 100%;\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin: 0;\n}\n\n.not_found_container {\n  width: 100%;\n}\n\n.not_found_main {\n  margin: 0 auto;\n}\n\n.not_found_svg {\n  width: 100%;\n  height: auto;\n  display: block;\n}\n\n@keyframes not_found_pulse {\n  0%,\n  100% {\n    opacity: 0.7;\n  }\n  50% {\n    opacity: 1;\n  }\n}\n\n/* SVG animations - with not_found prefix */\n.not_found_st0 {\n  fill: #fff;\n}\n.not_found_st2 {\n  fill: #5d89af;\n}\n.not_found_st3 {\n  fill: #709abf;\n}\n.not_found_st4,\n.not_found_st6 {\n  fill: #fff;\n  stroke: #b3dcdf;\n  stroke-miterlimit: 10;\n}\n.not_found_st6 {\n  stroke: #5d89af;\n  stroke-width: 2;\n}\n.not_found_st7,\n.not_found_st8,\n.not_found_st9 {\n  stroke: #709abf;\n  stroke-miterlimit: 10;\n}\n.not_found_st7 {\n  stroke-width: 5;\n  stroke-linecap: round;\n  fill: none;\n}\n.not_found_st8,\n.not_found_st9 {\n  fill: #fff;\n}\n.not_found_st9 {\n  fill: none;\n}\n\n#not_found_cloud1 {\n  animation: not_found_cloud003 15s linear infinite;\n}\n\n#not_found_cloud2 {\n  animation: not_found_cloud002 25s linear infinite;\n}\n\n#not_found_cloud3 {\n  animation: not_found_cloud003 20s linear infinite;\n}\n\n#not_found_cloud4 {\n  animation: not_found_float 4s linear infinite;\n}\n\n#not_found_cloud5 {\n  animation: not_found_float 8s linear infinite;\n}\n\n#not_found_tracks {\n  animation: not_found_slide 650ms linear infinite;\n}\n\n#not_found_bumps {\n  animation: not_found_land 10000ms linear infinite;\n}\n\n@keyframes not_found_jig {\n  0% {\n    transform: translateY(0px);\n  }\n  50% {\n    transform: translateY(1px);\n  }\n  100% {\n    transform: translateY(0px);\n  }\n}\n\n#not_found_car-layers {\n  animation: not_found_jig 0.35s linear infinite;\n}\n\n@keyframes not_found_land {\n  from {\n    transform: translateX(0);\n  }\n  to {\n    transform: translateX(1000px);\n  }\n}\n\n@keyframes not_found_slide {\n  from {\n    transform: translateX(0px);\n  }\n  to {\n    transform: translateX(100px);\n  }\n}\n\n@keyframes not_found_cloud002 {\n  0% {\n    transform: translateX(-1000px) translateY(3px);\n  }\n  100% {\n    transform: translateX(1000px) translateY(0);\n  }\n}\n\n@keyframes not_found_cloud003 {\n  0% {\n    transform: translateX(-1000px) translateY(3px);\n  }\n  100% {\n    transform: translateX(1000px) translateY(0);\n  }\n}\n\n@keyframes not_found_float {\n  0% {\n    transform: translateY(0px) translateX(0);\n  }\n  50% {\n    transform: translateY(8px) translateX(5px);\n  }\n  100% {\n    transform: translateY(0px) translateX(0);\n  }\n}\n\n#not_found_bracefront,\n#not_found_braceback {\n  animation: not_found_braces 1s linear infinite;\n}\n\n@keyframes not_found_braces {\n  0% {\n    transform: translateX(-2px);\n  }\n  25% {\n    transform: translateX(3px);\n  }\n  50% {\n    transform: translateX(-2px);\n  }\n  75% {\n    transform: translateX(3px);\n  }\n  100% {\n    transform: translateX(-2px);\n  }\n}\n\n@media (max-width: 600px) {\n  .not_found_title {\n    font-size: 2em;\n  }\n  .not_found_text {\n    font-size: 1em;\n  }\n  .not_found_btn {\n    padding: 12px 25px;\n  }\n  .not_found_container {\n    padding: 20px 10px;\n  }\n}\n"
